    sync_directory(parent)?;
    // A directory this call created is itself a new entry in its parent.
    if created_parent && let Some(grandparent) = parent.parent().filter(|dir| !dir.as_os_str().is_empty()) {
        sync_directory(grandparent)?;
    }
    Ok(())
