            .collect();
        if unresolved.is_empty() {
            Ok(())
        } else {
            Err(GraphError::IncompleteWorkspace { unresolved })
        }
    }

    /// Each package's id as reports print it.
    pub fn report_ids(&self) -> plan::ReportIds {
        plan::ReportIds::new(self.graph.packages())
