pub fn derive_selected_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
    workspace: &Workspace<'_, R, D>,
    plan: &VersionPlan,
    selections: &[ReleasePackageId],
) -> Result<ReleaseDecisionV1, GraphError> {
    let complete = derive_release_decision(workspace, plan)?;

    let mut seen = std::collections::BTreeSet::new();
    if let Some(duplicate) = selections.iter().find(|selection| !seen.insert(*selection)) {
        return Err(GraphError::ReleaseSelectionInvalid {
            package: duplicate.clone(),
            reason: ReleaseSelectionInvalidReason::Duplicate,
        });
    }

    let selected = selections.iter().collect::<std::collections::BTreeSet<_>>();
    for selection in &selected {
        let Some(package) = workspace_package(workspace, selection) else {
            let missing = callisto_model::PackageId::Prefixed {
                ecosystem: selection.ecosystem(),
                name: selection.name().to_string(),
            };
            return Err(GraphError::unknown_package(
                missing,
                workspace.graph.packages().map(Package::canonical_id),
            ));
        };
        let reason = if !complete.entries.iter().any(|entry| &entry.package == *selection) {
            ReleaseSelectionInvalidReason::NotARelease
        } else if package
            .publish_to
            .iter()
            .all(|target| matches!(target, callisto_model::PublishTarget::None))
        {
            ReleaseSelectionInvalidReason::NoDispatchableTarget
        } else {
            continue;
        };
        return Err(GraphError::ReleaseSelectionInvalid {
            package: (*selection).clone(),
            reason,
        });
    }

    let entries = expand_selection(workspace, complete.entries, &selected);
        self.publish = Some(outlook);
        self
    }
}

/// The publish outlook of `preview` on the versioned tree: plans exactly the packages the preview bumps that publish
/// somewhere. A bumped package with no publish target, such as a private member of a fixed group, is released with its
/// group but cannot be selected on its own (E169), so it is left out of the selection rather than reported as a failure.
/// `None` when a bumped package cannot be named, so nothing is claimed.
pub fn publish_outlook_in<R: callisto_model::CommandRunner, D: crate::resolver::DependencyResolver>(
    ws: &crate::Workspace<'_, R, D>,
    preview: &ReleasePreview,
) -> Option<PublishOutlook> {
    let mut publishable: Vec<callisto_model::ReleasePackageId> = Vec::new();
    let mut versioned_only: Vec<String> = Vec::new();
    for package in &preview.packages {
        let id: callisto_model::ReleasePackageId = package.release_id.as_deref()?.parse().ok()?;
        if crate::commands::release_decision::workspace_package(ws, &id)
            .is_some_and(crate::commands::release_decision::has_dispatchable_target)
        {
            publishable.push(id);
        } else {
            versioned_only.push(package.name.clone());
        }
    }
    let outlook = if publishable.is_empty() {
        publish_outlook(Ok(None))
    } else {
        publish_outlook(crate::commands::plan_workspace_release_offline(ws, &publishable))
    };
