            .into_iter()
            .flat_map(|rev| paths.iter().map(move |path| (rev.clone(), path.clone())))
            .collect();
        reads.preload(&wanted)?;
        if effective_version_at(reads, &commit, manifest)?
            .map(|found| found.version)
            .as_ref()
