    use std::path::Path;

    use callisto_model::{
        CommandError, CommandOutput, CommandRunner, Ecosystem, ExecutionTrustProfileV1, ReleaseDecisionV1,
        ReleasePackageId, SourceIdentity, Version, VersionGrammar,
    };

    use super::provider::PreparedOperation;
    use super::*;
    use crate::error::RemoteConflict;
    use crate::{DependencyResolver, GraphError, Workspace};

    pub(crate) struct RealGitRunner;
    impl CommandRunner for RealGitRunner {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            // A registry lookup never reaches the network from a test: every crate is unpublished.
            if program == "cargo" && args.contains(&"info") {
                let spec = args
                    .iter()
                    .skip_while(|arg| **arg != "info")
                    .nth(1)
                    .copied()
                    .unwrap_or_default();
                return Ok(CommandOutput {
                    exit_code: Some(101),
                    stdout: String::new(),
                    stderr: format!("error: could not find `{spec}` in registry `crates-io`\n"),
                });
            }
            let output = std::process::Command::new(program)
                .args(args)
                .current_dir(cwd)
                .output()
                .map_err(|error| CommandError::Io {
                    program: program.to_string(),
                    message: error.to_string(),
                })?;
            Ok(CommandOutput {
                exit_code: output.status.code(),
                stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
                stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
            })
        }

        fn run_with_stdin(
            &self,
            program: &str,
            args: &[&str],
            cwd: &Path,
            stdin: &[u8],
        ) -> Result<CommandOutput, CommandError> {
            callisto_fixtures::git::GitRunner.run_with_stdin(program, args, cwd, stdin)
        }
    }

    /// Real git except `ls-remote`, whose answer is read from a file. The
    /// fixture's `origin` is a real GitHub URL that must never be contacted.
    struct StubbedRemote {
        ls_remote: std::path::PathBuf,
    }
    impl CommandRunner for StubbedRemote {
        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
            if args.first() == Some(&"ls-remote") {
                return Ok(CommandOutput {
                    exit_code: Some(0),
                    stdout: std::fs::read_to_string(&self.ls_remote).unwrap_or_default(),
                    stderr: String::new(),
                });
            }
            RealGitRunner.run(program, args, cwd)
        }

        fn run_with_stdin(
            &self,
            program: &str,
            args: &[&str],
            cwd: &Path,
            stdin: &[u8],
        ) -> Result<CommandOutput, CommandError> {
            RealGitRunner.run_with_stdin(program, args, cwd, stdin)
        }
        let root = dir.path();
        let version_commit = inheriting_workspace(root);
        std::fs::write(root.join("crates/a/src/lib.rs"), "pub fn a() {}\n").unwrap();
        commit_all(root, "change a");
        assert_eq!(
            moved(root),
            vec![("cargo/a".to_owned(), Some(version_commit))],
            "a package that inherits its version is checked like any other"
        );
    }

    #[test]
    fn a_version_set_long_ago_is_still_found() {
        let (dir, _) = fixture();
        let root = dir.path();
        let version_commit = git(root, &["rev-parse", "HEAD"]);
        let manifest = root.join("Cargo.toml");
        let original = std::fs::read_to_string(&manifest).unwrap();
        for index in 0..105 {
            std::fs::write(&manifest, format!("{original}\n# edit {index}\n")).unwrap();
            commit_all(root, "touch the manifest");
        }
        assert_eq!(
            moved(root),
            vec![("cargo/release-fixture".to_owned(), Some(version_commit))],
            "more than a hundred manifest edits above the version commit must not hide it"
        );
    }

    #[test]
    fn a_release_branch_merged_after_unrelated_trunk_commits_is_not_a_move() {
        let (dir, _) = fixture();
        let root = dir.path();
        git(root, &["switch", "-q", "-c", "trunk"]);
        git(root, &["switch", "-q", "-c", "release"]);
        let manifest = root.join("Cargo.toml");
        let text = std::fs::read_to_string(&manifest).unwrap();
        std::fs::write(&manifest, text.replace("1.2.3", "1.3.0")).unwrap();
        commit_all(root, "release 1.3.0");
        git(root, &["switch", "-q", "trunk"]);
        std::fs::write(root.join("NOTES.md"), "trunk moved on\n").unwrap();
        commit_all(root, "trunk moved on");
        git(root, &["merge", "-q", "--no-ff", "-m", "merge the release", "release"]);
        assert!(
            moved(root).is_empty(),
            "HEAD is the merge that landed the version, so nothing differs from the commit that set it"
        );
    }

    #[test]
    fn a_version_no_commit_set_is_reported_without_a_commit() {
        let (dir, _) = fixture();
        let root = dir.path();
        let manifest = root.join("Cargo.toml");
        let text = std::fs::read_to_string(&manifest).unwrap();
